fn setup(){
 assert!(!r("build-plan.json").exists());let m=read(MANIFEST);let files=m["source_files_sha256"].as_object().unwrap();assert_eq!(files.len(),174);let mut pins=BTreeMap::new();
 for(f,h)in files{let from=Path::new(Z).join(f);assert_eq!(hash(&from),h.as_str().unwrap());let to=r("source").join(f);fs::create_dir_all(to.parent().unwrap()).unwrap();fs::copy(&from,&to).unwrap();pin(&mut pins,from);pin(&mut pins,to);}
 let new="crates/zopro-bn254/src/ifma8/loose_finish.rs";
 let module=r("source").join(new);fs::create_dir_all(module.parent().unwrap()).unwrap();fs::copy(r("loose_finish.rs"),&module).unwrap();pin(&mut pins,&module);
 let suffixes=[
 ("crates/zopro-bn254/src/ifma8.rs","\n#[cfg(zopro_loose_g1_finish)] mod loose_finish;\n"),
 ("crates/zopro-core/src/simd.rs","\n#[cfg(all(zopro_loose_g1_finish,feature=\"ifma8\",target_arch=\"x86_64\",target_feature=\"avx512ifma\",target_feature=\"avx512vl\",target_feature=\"avx512dq\",not(no_ifma)))]\nimpl FqBatch { #[inline(always)] pub(crate) fn loose_finish(&self,ax:&Self,ay:&Self,sum:&Self)->([Fq;8],[Fq;8]) {self.0.affine_finish_loose(&ax.0,&ay.0,&sum.0)} }\n")];
 for(f,suffix)in suffixes{let p=r("source").join(f);let s=fs::read_to_string(&p).unwrap();fs::write(&p,format!("{s}{suffix}")).unwrap();pin(&mut pins,&p);}
 let p=r("source/crates/zopro-core/src/msm.rs");let original=fs::read_to_string(&p).unwrap();
 let before="        let x = slope.mul(&slope).sub(&g.xsum);\n        let y = slope.mul(&g.ax.sub(&x)).sub(&g.ay);\n        let (x, y) = (x.get(), y.get());";
 let after="        #[cfg(all(zopro_loose_g1_finish,feature=\"ifma8\",target_arch=\"x86_64\",target_feature=\"avx512ifma\",target_feature=\"avx512vl\",target_feature=\"avx512dq\",not(no_ifma)))] let loose=if FAST{Some(slope.loose_finish(&g.ax,&g.ay,&g.xsum))}else{None};\n        #[cfg(not(all(zopro_loose_g1_finish,feature=\"ifma8\",target_arch=\"x86_64\",target_feature=\"avx512ifma\",target_feature=\"avx512vl\",target_feature=\"avx512dq\",not(no_ifma))))] let loose:Option<([Fq;LANES],[Fq;LANES])>=None;\n        let (x,y)=loose.unwrap_or_else(||{let x=slope.mul(&slope).sub(&g.xsum);let y=slope.mul(&g.ax.sub(&x)).sub(&g.ay);(x.get(),y.get())});";
 assert_eq!(original.matches(before).count(),1);let modified=original.replace(before,after);assert_eq!(modified.replace(after,before),original);fs::write(&p,modified).unwrap();pin(&mut pins,&p);
 let mut exact=0;
 for(f,h)in files{let p=r("source").join(f);if hash(&p)==h.as_str().unwrap(){exact+=1;}else{let mut s=fs::read_to_string(&p).unwrap();for(ff,suffix)in suffixes{if f==ff{s=s.strip_suffix(suffix).unwrap().into();}}if f=="crates/zopro-core/src/msm.rs"{s=s.replace(after,before);}assert_eq!(format!("{:x}",Sha256::digest(s.as_bytes())),h.as_str().unwrap());}}
 assert_eq!(exact,171);
 save(r("source-audit.json"),&json!({"original_files":174,"private_files":175,"originals_exact":171,"reverse174_exact":true,"suffixes":suffixes,"msm_before":before,"msm_after":after,"new_module":new,"original_nonfused_CIOS_body_unchanged":true,"field_generation_parent_unchanged":true,"heap_scratch_geometry_unchanged":true,"production_changed":false}));
 let history=["docs/benchmarks/2026-10-26-lazy-linear/README.md","docs/benchmarks/2026-10-28-g1-weighted-anchor-sdk/README.md","docs/benchmarks/2026-10-28-signed-final-sub-sdk174/README.md","docs/benchmarks/2026-10-24-canonical-y-output/README.md"];
 let mut hist=BTreeMap::new();for f in history{pin(&mut hist,Path::new(Z).join(f));pin(&mut pins,Path::new(Z).join(f));}save(r("history-audit.json"),&json!({"closed_trials":hist,"difference":"local loose 4p/5p coordinate finish;one wide nonfused multiply;canonical export;no quotient estimator,forward weighted record or original-lazy-bit fusion","new_performance_claim":false}));
 let flags=m["rustflags"].as_str().unwrap();fs::write(r("native-flags.txt"),flags).unwrap();let cargo=r("source/Cargo.toml");let mut steps=Vec::new();
 for label in ["control","candidate"]{let flag=if label=="control"{flags.to_string()}else{format!("{flags} --cfg zopro_loose_g1_finish")};let env=json!({"RUSTFLAGS":flag,"CARGO_TARGET_DIR":r(format!("target-{label}")),"CARGO_BUILD_JOBS":"16","RAYON_NUM_THREADS":"4","ZOPRO_CPU_DEDUP":"1","ZOPRO_CPU_ZERO_AWARE_GROUPS":"1","ZOPRO_CPU_PACKED":"1","ZOPRO_CPU_DIRECT":"1","ZOPRO_CPU_CANONICAL_BATCH":"1","ZOPRO_CPU_VECTOR_INVERSE":"1","ZOPRO_CPU_G2_PREFIX_RECORDS":"1","ZOPRO_CPU_G1_SCRATCH_STORE":"2"});
  for package in ["zopro-bn254","zopro-core"]{let required=if label=="candidate"&&package=="zopro-bn254"{vec!["ifma8::loose_finish::tests::loose_finish_matches_independent_arkworks_and_canonical_exports"]}else{vec![]};steps.push(json!({"kind":"command","name":format!("{package}-{label}"),"argv":["cargo","test","--manifest-path",cargo,"--locked","--offline","--release","-p",package,"--lib","--","--test-threads=1","--nocapture"],"environment":env,"unfiltered":true,"required_tests":required,"timeout_seconds":1800}));}
  steps.push(json!({"kind":"command","name":format!("zopro-prover-{label}"),"argv":["cargo","test","--manifest-path",cargo,"--locked","--offline","--release","-p","zopro-prover","--lib","--test","cubic","--","--test-threads=1"],"environment":env,"unfiltered":true,"timeout_seconds":1800}));
  steps.push(json!({"kind":"command","name":format!("libraries-{label}"),"argv":["cargo","build","--manifest-path",cargo,"--locked","--offline","--release","-p","zopro-bench","--lib","--message-format=json"],"environment":env,"timeout_seconds":1800}));
  steps.push(json!({"kind":"command","name":format!("freeze-{label}"),"argv":[r("native-helper"),"freeze",label],"environment":env,"timeout_seconds":180}));
  steps.push(json!({"kind":"link-sdk","name":label,"artifacts":r(format!("frozen-{label}-cargo.jsonl")),"driver":Path::new(Z).join("crates/zopro-bench/examples/cpu-sdk.rs"),"additional_sources":[Path::new(Z).join("crates/zopro-bench/examples/support/perf.rs")],"timeout_seconds":600}));
 }
 for f in ["native.rs","native-helper","setup.rs","adapt.rs","loose_finish.rs","design.md","bounds.md","source-audit.json","history-audit.json","native-flags.txt"]{pin(&mut pins,r(f));}pin(&mut pins,MANIFEST);
 save(r("build-pins.json"),&json!(pins));save(r("build-plan.json"),&json!({"version":1,"source_pins":r("build-pins.json"),"steps":steps}));println!("Prepared12native steps175source/171exact/reverse174;bounded loose G1 finish;no new heap");
}
